-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.sync_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  begin
    update public.profiles p
       set name = coalesce(left(coalesce(new.raw_user_meta_data ->> 'full_name',
                                         new.raw_user_meta_data ->> 'name'), 200), p.name),
           avatar_url = coalesce(new.raw_user_meta_data ->> 'avatar_url', p.avatar_url)
     where p.id = new.id;
  exception when others then
    raise warning 'sync_profile: %', sqlerrm;
  end;
  return null;
end;
$function$;

grant execute on function public.sync_profile() to service_role;
